defmodule Mix.Tasks.LiveLift.Compile do
  use Mix.Task

  alias LiveLift.Client.Assets

  @shortdoc "Compiles LiveLift views and checks the browser runtime during bundling"

  @impl Mix.Task
  def run(args) do
    {opts, modules, invalid} =
      OptionParser.parse(args,
        strict: [output: :string, runtime_output: :string, npm_runtime: :boolean, split: :boolean]
      )

    unless invalid == [] and modules == [] and is_binary(opts[:output]) and
             not (opts[:npm_runtime] == true and is_binary(opts[:runtime_output])) do
      Mix.raise(
        "usage: mix live_lift.compile --output assets/js/generated_views.js [--runtime-output assets/js/live_lift_runtime.js | --npm-runtime] [--split]"
      )
    end

    Mix.Task.run("compile")

    app = Mix.Project.config()[:app]

    case Application.load(app) do
      :ok -> :ok
      {:error, {:already_loaded, ^app}} -> :ok
    end

    view_modules =
      app
      |> Application.spec(:modules)
      |> Enum.filter(fn module ->
        Code.ensure_loaded?(module) and
          function_exported?(module, :__live_lift_client_template__, 0) and
          is_list(module.__live_lift_client_template__())
      end)

    output = Path.expand(opts[:output])

    {specifier, binding, runtime} = Assets.runtime(output, opts)
    link = Assets.link(specifier, binding)

    File.mkdir_p!(Path.dirname(output))

    if opts[:split] do
      write_split_registry(view_modules, output, link)
    else
      write_registry(view_modules, output, link)
    end

    Assets.write_registry_types(output, specifier)
    Assets.write_runtime(runtime, binding)

    Mix.shell().info("Generated #{Path.relative_to_cwd(output)} (#{length(view_modules)} views)")
  end

  defp write_registry(modules, output, link) do
    {registry, source_map} =
      LiveLift.Client.Compiler.compile_registry_with_map(modules, output)

    File.write!(output, registry <> link <> "//# sourceMappingURL=#{Path.basename(output)}.map\n")
    File.write!(output <> ".map", source_map)
  end

  defp write_split_registry(modules, output, link) do
    directory = Path.rootname(output) <> "_views"
    File.mkdir_p!(directory)
    relative_directory = Path.basename(directory)

    entries =
      modules
      |> Enum.reject(&function_exported?(&1, :__live_lift_component__, 0))
      |> Enum.sort()
      |> Enum.map(fn module ->
        name = Atom.to_string(module) |> String.replace_prefix("Elixir.", "")
        filename = URI.encode(name, &URI.char_unreserved?/1) <> ".js"
        write_registry([module], Path.join(directory, filename), "")
        import_path = Jason.encode!("./#{relative_directory}/#{filename}")
        "  [#{Jason.encode!(name)}]: () => import(#{import_path})"
      end)

    File.write!(
      output,
      "// Generated by LiveLift. Do not edit.\nexport const views = {\n" <>
        Enum.join(entries, ",\n") <> "\n};\n" <> link
    )
  end
end
